      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory gave strongly correlated electron physics a broadly useful, nonperturbative framework and reshaped the study of materials.",
        "attribution": "Georges, Vollhardt, and Kotliar are central to developing and establishing the method; the wider community's extensions should be distinguished from its foundational formulation.",
        "maturity": "The framework has had decades of extensive use and experimental engagement.",
        "uncertainties": [
          "The division of credit among the three foundational contributors depends on which aspects of the formulation and early applications are emphasized."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and realization of correlated phases in twisted bilayer graphene opened a new route to engineer and investigate quantum matter.",
        "attribution": "Bistritzer and MacDonald supplied the key continuum-band prediction; Jarillo-Herrero's group demonstrated the striking correlated phenomena.",
        "maturity": "The central results have been repeatedly investigated, though the field remains active and the detailed phase diagram continues to develop.",
        "uncertainties": [
          "The relationship between superconductivity and neighboring correlated phases remains unsettled."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B024",
      "proposed_laureates": [
        "A. Peter Young",
        "Bertrand I. Halperin",
        "David R. Nelson"
      ],
      "assessment": {
        "nobel_worthiness": "The theory of defect-mediated two-dimensional melting and the hexatic phase is a deep, influential application of statistical mechanics and topological defects.",
        "attribution": "Halperin and Nelson developed the central theory, with Young making major independent and complementary contributions to its formulation.",
        "maturity": "The framework has been tested across systems and has remained foundational over several decades.",
        "uncertainties": [
          "Real materials and finite-size systems can depart from the idealized sequence of transitions, complicating direct identification of the predicted phases."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B044",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Denis J. Evans",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "Fluctuation relations and stochastic thermodynamics extend thermodynamic reasoning to driven, small, and far-from-equilibrium systems with lasting conceptual and practical influence.",
        "attribution": "Evans established early fluctuation relations, Jarzynski derived a powerful nonequilibrium work identity, and Seifert built a broad stochastic thermodynamics framework; Crooks is also a major contributor.",
        "maturity": "The core relations have extensive theoretical and experimental confirmation and are established across multiple fields.",
        "uncertainties": [
          "The work is distributed among several foundational results and contributors, making a three-person attribution difficult."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B015",
      "proposed_laureates": [
        "John Toner",
        "Tamás Vicsek",
        "Yuhai Tu"
      ],
      "assessment": {
        "nobel_worthiness": "The hydrodynamic theory of flocking identified robust collective behavior and an organizing framework for nonequilibrium active matter.",
        "attribution": "Vicsek established influential particle models and simulations; Toner and Tu developed the central continuum theory and its predictions.",
        "maturity": "The theory has shaped a mature research area and prompted substantial tests and extensions across active systems.",
        "uncertainties": [
          "The degree to which the original universality claims apply across real biological and synthetic flocks remains actively examined."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Claudio Castelnovo",
        "Roderich Moessner",
        "Steven T. Bramwell"
      ],
      "assessment": {
        "nobel_worthiness": "Spin ice provides a vivid realization of emergent magnetic monopole-like excitations and demonstrates how collective behavior can produce effective particles absent at the microscopic level.",
        "attribution": "Bramwell and collaborators established key experimental signatures; Castelnovo and Moessner gave the influential theoretical account of emergent monopoles.",
        "maturity": "The characteristic spin-ice behavior is well established, with extensive subsequent study of its excitations and dynamics.",
        "uncertainties": [
          "The monopoles are emergent quasiparticles in a constrained material, not isolated fundamental magnetic charges."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision measurement and enabled stringent tests of fundamental physics using atomic transitions.",
        "attribution": "Katori and Ye made distinct, complementary contributions to the clock concept and its experimental realization.",
        "maturity": "The technology is mature, with repeated demonstrations of exceptional accuracy and continuing improvements.",
        "uncertainties": [
          "The field's progress relies on broad international experimental and technical contributions beyond these two pioneers."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation and the quantum origin of cosmic structure offer an exceptionally consequential account of early-universe physics and the origin of observed large-scale structure.",
        "attribution": "Guth and Linde developed influential inflationary proposals; Mukhanov made foundational contributions to the theory of primordial perturbations.",
        "maturity": "The framework has produced successful predictions, but key claims about inflation's specific mechanism and primordial gravitational waves remain unconfirmed.",
        "uncertainties": [
          "Many inflationary models can fit current observations, and the distinctive physical process has not been identified."
        ]
      }
    }
  ]
